   487	                           void* ptr,
   488	                           std::size_t bytes,
   489	                           [[maybe_unused]] std::size_t alignment) noexcept
   490	{
   491	  auto tracking_bytes           = rmm::align_up(bytes, rmm::CUDA_ALLOCATION_ALIGNMENT);
   492	  auto upstream_reclaimed_bytes = tracking_bytes;
   493	  auto* reservation_state       = _allocation_tracker->get_tracker_state(stream);
   494	  if (reservation_state != nullptr) {
   495	    auto* reservation     = reservation_state->memory_reservation.get();
   496	    auto reservation_size = static_cast<int64_t>(reservation->size());
   497	    int64_t post_deallocation_size =
   498	      reservation->allocated_bytes.sub(static_cast<int64_t>(tracking_bytes));
   499	    int64_t pre_deallocation_size = post_deallocation_size + static_cast<int64_t>(tracking_bytes);
   500	    if (pre_deallocation_size <= reservation_size) {
   501	      // if it was made using the reserved space
   502	      upstream_reclaimed_bytes = 0;
   503	    } else if (post_deallocation_size < reservation_size) {
   504	      // if it was partially made using the reserved space
   505	      upstream_reclaimed_bytes = static_cast<std::size_t>(pre_deallocation_size - reservation_size);
