   549	  int64_t allocation_size    = arena->allocated_bytes.load();
   550	  int64_t arena_size         = arena->size();
   551	  std::size_t released_bytes = 0;
   552	  if (arena_size > allocation_size) {
   553	    released_bytes = static_cast<std::size_t>(arena_size - allocation_size);
