   265	void task_scheduler::drain_after_error()
   266	{
   267	  SIRIUS_LOG_INFO("task_scheduler: draining after error");
   268	  // Teardown ordering is load-bearing. The scan/gpu executor drains below run
   269	  // in-flight tasks to completion, and a completing task schedules its
   270	  // downstream consumers via task_creator::schedule() (gpu_pipeline_executor and
   271	  // duckdb_scan_executor both do this). Each such request holds a raw
   272	  // sirius_physical_operator* owned by the engine, which is destroyed the moment
   273	  // execute() returns. If the task_creator is live (or restarted) while those
   274	  // requests are still in flight, its manager_loop dereferences a freed operator
   275	  // in get_operator_for_next_task() — a use-after-free that crashes intermittently
   276	  // under multi-partition sort with many in-flight pipeline tasks.
   277	  //
   278	  // So: stop the task_creator FIRST and keep its queue interrupted across the
   279	  // executor drains. With the queue interrupted, schedule() pushes from
   280	  // completion callbacks return false and the requests (and their dangling
   281	  // operator pointers) are dropped instead of processed. Only AFTER every
   282	  // executor has quiesced do we drain the creation queue and restart the
   283	  // creator for the next query.
   284	  if (_task_creator) { _task_creator->stop_thread_pool(); }
   285	
   286	  // Drain the top-level task queue so management_eventloop doesn't dispatch
   287	  // stale tasks from the failed query.
   288	  _task_queue.drain();
   289	
   290	  // Interrupt each GPU executor's manager loop, wait for in-flight thread-pool
   291	  // tasks to finish, then restart the manager for the next query.
   292	  for (auto& [device_id, gpu_exec] : _gpu_executors) {
   293	    gpu_exec->drain_and_wait();
   294	  }
   295	
   296	  // Now that no executor can generate further task_creation_requests, discard
   297	  // any that accumulated (and release the shared_ptr<data_batch> references they
   298	  // hold, which would otherwise survive clear_all_repositories at QueryEnd and
   299	  // show up as inter-iteration "memory leak" warnings). drain_pending_tasks()
   300	  // reactivates the queue when done.
   301	  if (_task_creator) { _task_creator->drain_pending_tasks(); }
   302	
   303	  // Belt-and-suspenders: the executor restarts above emit device_ready signals,
   304	  // and the management loop may have dispatched a leftover task into an executor
   305	  // queue between the two drains. Clear the top-level queue once more so the
   306	  // next query starts from empty.
   307	  _task_queue.drain();
   308	
   309	  if (_task_creator) { _task_creator->start_thread_pool(); }
   310	  SIRIUS_LOG_INFO("task_scheduler: DONE draining after error");
   311	}
