    96	void itask_executor::drain_and_wait()
    97	{
    98	  // Guard: if the executor has never been started (or has been stopped),
    99	  // _bounded_pool is nullptr. drain_after_error may legitimately be called
   100	  // before any work has been dispatched, in which case there is nothing to
   101	  // drain. Without this guard the next line dereferences nullptr and crashes
   102	  // inside pthread_mutex_lock on the (offset-zero) std::mutex member —
   103	  // observed during task_scheduler::drain_after_error after an early
   104	  // sirius_engine::execute failure.
   105	  if (!_bounded_pool) {
   106	    SIRIUS_LOG_INFO("itask_executor::drain_and_wait: skipped — pool not initialized");
   107	    return;
   108	  }
   109	
   110	  // Interrupt the pool so the manager's reserve() unblocks with an invalid slot.
   111	  _bounded_pool->interrupt();
   112	
   113	  // Interrupt pop() so the manager loop sees a nullptr and breaks out.
   114	  _task_queue.interrupt();
   115	
   116	  // Join the manager thread so we know it has exited.
   117	  if (_manager_thread.joinable()) { _manager_thread.join(); }
