   119	  // Wait for all in-flight thread-pool tasks to finish.
   120	  _bounded_pool->wait_all();
   121	
   122	  // Clear any remaining tasks from the queue.
   123	  _task_queue.drain();
   124	
   125	  // Re-enable the pool and queue so the executor is ready for the next query.
   126	  _bounded_pool->resume();
   127	  _task_queue.reactivate();
   128	  _manager_thread = std::thread([this] { manager_loop(); });
   129	}
