  1555	void SiriusContext::acquire_query_lifecycle_slot(ClientContext* context)
  1556	{
  1557	  // `| 1` keeps the sentinel (0 = free) unreachable; a cross-thread hash
  1558	  // collision could only cause a spurious diagnosable error, never a missed
  1559	  // release (the check is advisory — correctness rests on the scope-bound
  1560	  // release).
  1561	  auto const my_hash = std::hash<std::thread::id>{}(std::this_thread::get_id()) | 1;
  1562	  // Same-thread reacquire would be a silent permanent wait (plain std::mutex).
  1563	  // Only the CURRENT holder can observe its own hash here, so a match is a
  1564	  // definite programming error — surface it as a diagnosable error instead.
  1565	  if (holder_thread_hash_.load(std::memory_order_relaxed) == my_hash) {
  1566	    throw std::runtime_error(
  1567	      "Sirius internal error: query-lifecycle slot re-acquired on the holding thread "
  1568	      "(nested execution window)");
  1569	  }
  1570	  // Fast-fail before waiting: no point queuing on an unavailable runtime or
  1571	  // for an already-cancelled query.
  1572	  if (runtime_unavailable_.load(std::memory_order_acquire)) { throw_runtime_unavailable(); }
  1573	  if (context && context->IsInterrupted()) { throw InterruptException(); }
  1574	
  1575	  query_lifecycle_mutex_.lock();
  1576	  holder_thread_hash_.store(my_hash, std::memory_order_relaxed);
  1577	  query_lifecycle_held_.store(true, std::memory_order_release);
  1578	
  1579	  // Re-check AFTER acquiring, BEFORE any shared mutation: the previous holder
  1580	  // may have latched unavailability, and this waiter may have been cancelled,
  1581	  // while it was blocked. A cancelled waiter must never late-enter the window.
  1582	  if (runtime_unavailable_.load(std::memory_order_acquire)) {
  1583	    release_query_lifecycle_slot();
  1584	    throw_runtime_unavailable();
  1585	  }
  1586	  if (context && context->IsInterrupted()) {
  1587	    release_query_lifecycle_slot();
  1588	    throw InterruptException();
  1589	  }
  1590	}
  1591	
  1592	void SiriusContext::release_query_lifecycle_slot() noexcept
  1593	{
  1594	  holder_thread_hash_.store(0, std::memory_order_relaxed);
  1595	  query_lifecycle_held_.store(false, std::memory_order_release);
  1596	  query_lifecycle_mutex_.unlock();
  1597	}
