   366	  auto global_state = std::make_shared<oom_test_global_state>();
   367	
   368	  const int num_tasks = 3;
   369	  std::atomic<int> dispatched{0};
   370	
   371	  f.executor->start();
   372	
   373	  // Post-v1.0 push-model (commit 90dc104): gpu_pipeline_executor no longer publishes
   374	  // task_requests. Schedule tasks directly onto the executor instead of waiting on
   375	  // f.request_channel.get(). The request_channel is kept wired to preserve the
   376	  // fixture API but is not used at runtime.
   377	  std::thread request_handler([&]() {
   378	    while (dispatched.load(std::memory_order_relaxed) < num_tasks) {
   379	      auto local_state = std::make_unique<sirius::pipeline::gpu_pipeline_task_local_state>(
   380	        std::make_unique<sirius::op::pipelineable_operator_data>(
