   395	  auto timeout    = std::chrono::seconds(30);
   396	  while (global_state->completed_count.load(std::memory_order_relaxed) < num_tasks) {
   397	    std::this_thread::sleep_for(std::chrono::milliseconds(50));
   398	    if (std::chrono::steady_clock::now() - start_time > timeout) {
